export interface UserPreferences {
  theme: string;
  notifications: boolean;
  language: string;
}

export interface User {
  id: number;
  name: string;
  email: string;
  preferences: UserPreferences;
  tags: string[];
  last_login: string;
  metadata: Record<string, unknown> | null;
}

export function validateUser(input: unknown): input is User {
  if (typeof input !== "object" || input === null) {
    return false;
  }

  const user = input as Record<string, unknown>;

  if (typeof user.id !== "number" || !Number.isInteger(user.id)) {
    return false;
  }

  if (typeof user.name !== "string" || user.name.length === 0) {
    return false;
  }

  if (typeof user.email !== "string" || !user.email.includes("@")) {
    return false;
  }

  if (typeof user.preferences !== "object" || user.preferences === null) {
    return false;
  }

  const preferences = user.preferences as Record<string, unknown>;

  if (typeof preferences.theme !== "string") {
    return false;
  }

  if (typeof preferences.notifications !== "boolean") {
    return false;
  }

  if (typeof preferences.language !== "string") {
    return false;
  }

  if (
    !Array.isArray(user.tags) ||
    !user.tags.every((tag) => typeof tag === "string")
  ) {
    return false;
  }

  if (typeof user.last_login !== "string") {
    return false;
  }

  if (
    user.metadata !== null &&
    (typeof user.metadata !== "object" ||
      user.metadata === null ||
      Array.isArray(user.metadata))
  ) {
    return false;
  }

  return true;
}
