#!/usr/bin/env python3

import argparse
import re
import sys
from pathlib import Path

LOG_LEVELS = ("INFO", "WARN", "ERROR", "DEBUG")
LEVEL_PATTERN = re.compile(r"\b(INFO|WARN|ERROR|DEBUG)\b", re.IGNORECASE)


def count_levels(path: Path):
    counts = {level: 0 for level in LOG_LEVELS}

    try:
        with path.open("r", encoding="utf-8", errors="replace") as f:
            for line in f:
                for match in LEVEL_PATTERN.finditer(line):
                    level = match.group(1).upper()
                    counts[level] += 1
    except OSError as exc:
        print(f"Warning: could not read {path}: {exc}", file=sys.stderr)
        return None

    return counts


def format_table(headers, rows):
    if not rows:
        return "No files matched."

    widths = []
    for i, header in enumerate(headers):
        width = len(header)
        for row in rows:
            width = max(width, len(str(row[i])))
        widths.append(width)

    lines = []
    lines.append(" | ".join(str(h).ljust(w) for h, w in zip(headers, widths)))
    lines.append("-+-".join("-" * w for w in widths))

    for row in rows:
        lines.append(" | ".join(str(c).ljust(w) for c, w in zip(row, widths)))

    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(
        description="Summarize log levels in .log files."
    )
    parser.add_argument(
        "directory",
        type=Path,
        help="Directory containing .log files",
    )
    parser.add_argument(
        "--min-errors",
        type=int,
        default=0,
        help="Only show files with at least N ERROR entries (default: 0)",
    )

    args = parser.parse_args()

    if args.min_errors < 0:
        parser.error("--min-errors must be >= 0")

    directory = args.directory

    if not directory.exists():
        print(f"Error: directory not found: {directory}", file=sys.stderr)
        return 2

    if not directory.is_dir():
        print(f"Error: not a directory: {directory}", file=sys.stderr)
        return 2

    log_files = sorted(
        [
            p
            for p in directory.iterdir()
            if p.is_file() and p.suffix.lower() == ".log"
        ],
        key=lambda p: p.name,
    )

    if not log_files:
        print(f"No .log files found in {directory}")
        return 0

    rows = []
    for path in log_files:
        counts = count_levels(path)
        if counts is None:
            continue

        if counts["ERROR"] >= args.min_errors:
            rows.append(
                [
                    path.name,
                    counts["INFO"],
                    counts["WARN"],
                    counts["ERROR"],
                    counts["DEBUG"],
                ]
            )

    print(format_table(["FILE", "INFO", "WARN", "ERROR", "DEBUG"], rows))
    return 0


if __name__ == "__main__":
    sys.exit(main())
